import 'dart:convert';
import 'package:flutter/services.dart';
import 'app_log.dart';
import 'http_camera_protocol.dart';

/// Manages bundled firmware images and version comparison.
///
/// Firmware files are stored in `assets/firmware/`:
/// - `manifest.json` — version and size metadata
/// - `boot.img` — Android boot image (~4MB)
/// - `rootfs.img` — SquashFS root filesystem (~5-6MB)
///
/// The manifest is generated by the firmware build script (build_firmware.sh)
/// and must be kept in sync with the actual image files.
class FirmwareService {
  static const _manifestPath = 'assets/firmware/manifest.json';
  static const _bootPath = 'assets/firmware/boot.img';
  static const _rootfsPath = 'assets/firmware/rootfs.img';

  FirmwareManifest? _manifest;
  bool _manifestLoaded = false;

  /// Load and cache the firmware manifest from assets.
  Future<FirmwareManifest?> loadManifest() async {
    if (_manifestLoaded) return _manifest;
    _manifestLoaded = true;

    try {
      final jsonStr = await rootBundle.loadString(_manifestPath);
      final json = jsonDecode(jsonStr) as Map<String, dynamic>;
      _manifest = FirmwareManifest.fromJson(json);
      AppLog.info('Firmware', 'Manifest loaded: version=${_manifest!.version}');
    } catch (e) {
      AppLog.info('Firmware', 'No firmware manifest found (OTA disabled): $e');
      _manifest = null;
    }
    return _manifest;
  }

  /// The cached manifest, or null if not loaded / not available.
  FirmwareManifest? get manifest => _manifest;

  /// Load boot.img bytes from assets.
  ///
  /// Throws if the file is not present in assets.
  Future<Uint8List> loadBootImage() async {
    final data = await rootBundle.load(_bootPath);
    return data.buffer.asUint8List();
  }

  /// Load rootfs.img bytes from assets.
  ///
  /// Throws if the file is not present in assets.
  Future<Uint8List> loadRootfsImage() async {
    final data = await rootBundle.load(_rootfsPath);
    return data.buffer.asUint8List();
  }

  /// Whether firmware images are bundled in the app.
  ///
  /// Returns true if the manifest exists and both image sizes are > 0.
  /// When false, OTA update is not available (no firmware to push).
  Future<bool> hasFirmware() async {
    final m = await loadManifest();
    if (m == null) return false;
    return m.bootSize > 0 && m.rootfsSize > 0;
  }

  /// Compare camera firmware version with bundled version.
  ///
  /// Returns true if the camera firmware is older than the bundled version,
  /// meaning an update is available.
  /// Returns false if versions match, camera is newer, or no firmware bundled.
  bool needsUpdate(String? cameraFwVersion) {
    if (_manifest == null) return false;
    return HttpCameraProtocol.needsFirmwareUpdate(
        cameraFwVersion, _manifest!.version);
  }
}

/// Firmware manifest parsed from assets/firmware/manifest.json.
class FirmwareManifest {
  final String version; // e.g. "V0.5-20260730"
  final int bootSize; // boot.img size in bytes
  final int rootfsSize; // rootfs.img size in bytes

  const FirmwareManifest({
    required this.version,
    required this.bootSize,
    required this.rootfsSize,
  });

  factory FirmwareManifest.fromJson(Map<String, dynamic> json) {
    return FirmwareManifest(
      version: json['version'] as String? ?? '',
      bootSize: (json['boot_size'] as num?)?.toInt() ?? 0,
      rootfsSize: (json['rootfs_size'] as num?)?.toInt() ?? 0,
    );
  }
}
